"use strict";(self.webpackChunk=self.webpackChunk||[]).push([["2773"],{610:function(s,a,n){n.r(a),n.d(a,{default:function(){return p}});var t=n(1147);let l=["innerHTML"],p={setup:()=>({html:""}),render:()=>((0,t.wg)(),(0,t.iD)("div",{class:"mi-doc-markdown-body",innerHTML:'<h1>分步表单页</h1>\n<div class="mi-doc-card"><h3 id="jie-shao" tabindex="-1">介绍</h3>\n<p>分步表单页适合报名、审批、信息补录、线索收集等需要逐步确认信息的移动业务页面。</p>\n<p>该场景使用 <code>Steps</code>、<code>Form</code>、<code>Field</code>、<code>CellGroup</code>、<code>Button</code> 和 <code>Tag</code> 组合出一个两段式录入页面，强调当前步骤、核心字段、只读选择入口和底部主操作。</p>\n</div><div class="mi-doc-card"><h3 id="tui-jian-zu-jian" tabindex="-1">推荐组件</h3>\n<table>\n<thead>\n<tr>\n<th>组件</th>\n<th>作用</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Steps</td>\n<td>展示填写进度</td>\n</tr>\n<tr>\n<td>Form</td>\n<td>管理提交和校验</td>\n</tr>\n<tr>\n<td>Field</td>\n<td>输入业务字段</td>\n</tr>\n<tr>\n<td>CellGroup</td>\n<td>聚合表单区域</td>\n</tr>\n<tr>\n<td>Tag</td>\n<td>标记当前资料状态</td>\n</tr>\n<tr>\n<td>Button</td>\n<td>触发下一步或提交</td>\n</tr>\n</tbody>\n</table>\n</div><div class="mi-doc-card"><h3 id="shi-li-dai-ma" tabindex="-1">示例代码</h3>\n<pre><code class="language-html"><span class="hljs-tag">&lt;<span class="hljs-name">mi-nav-bar</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;预约报名&quot;</span> <span class="hljs-attr">left-arrow</span> <span class="hljs-attr">left-text</span>=<span class="hljs-string">&quot;返回&quot;</span> /&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-steps</span> <span class="hljs-attr">:active</span>=<span class="hljs-string">&quot;1&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-step</span>&gt;</span>填写信息<span class="hljs-tag">&lt;/<span class="hljs-name">mi-step</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-step</span>&gt;</span>确认资料<span class="hljs-tag">&lt;/<span class="hljs-name">mi-step</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-step</span>&gt;</span>提交完成<span class="hljs-tag">&lt;/<span class="hljs-name">mi-step</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">mi-steps</span>&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-form</span> @<span class="hljs-attr">submit</span>=<span class="hljs-string">&quot;onSubmit&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-cell-group</span> <span class="hljs-attr">inset</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;基础信息&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">mi-field</span>\n            <span class="hljs-attr">v-model</span>=<span class="hljs-string">&quot;name&quot;</span>\n            <span class="hljs-attr">name</span>=<span class="hljs-string">&quot;name&quot;</span>\n            <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;联系人&quot;</span>\n            <span class="hljs-attr">placeholder</span>=<span class="hljs-string">&quot;请输入姓名&quot;</span>\n            <span class="hljs-attr">:rules</span>=<span class="hljs-string">&quot;[{ required: true, message: &#x27;请输入联系人&#x27; }]&quot;</span>\n        /&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">mi-field</span>\n            <span class="hljs-attr">v-model</span>=<span class="hljs-string">&quot;mobile&quot;</span>\n            <span class="hljs-attr">name</span>=<span class="hljs-string">&quot;mobile&quot;</span>\n            <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;手机号&quot;</span>\n            <span class="hljs-attr">placeholder</span>=<span class="hljs-string">&quot;请输入手机号&quot;</span>\n            <span class="hljs-attr">:rules</span>=<span class="hljs-string">&quot;[{ required: true, message: &#x27;请输入手机号&#x27; }]&quot;</span>\n        /&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">mi-cell-group</span>&gt;</span>\n\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-cell-group</span> <span class="hljs-attr">inset</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;预约信息&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">mi-field</span>\n            <span class="hljs-attr">v-model</span>=<span class="hljs-string">&quot;date&quot;</span>\n            <span class="hljs-attr">readonly</span>\n            <span class="hljs-attr">is-link</span>\n            <span class="hljs-attr">name</span>=<span class="hljs-string">&quot;date&quot;</span>\n            <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;到店日期&quot;</span>\n            <span class="hljs-attr">placeholder</span>=<span class="hljs-string">&quot;请选择日期&quot;</span>\n        /&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">mi-field</span>\n            <span class="hljs-attr">v-model</span>=<span class="hljs-string">&quot;store&quot;</span>\n            <span class="hljs-attr">readonly</span>\n            <span class="hljs-attr">is-link</span>\n            <span class="hljs-attr">name</span>=<span class="hljs-string">&quot;store&quot;</span>\n            <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;预约门店&quot;</span>\n            <span class="hljs-attr">placeholder</span>=<span class="hljs-string">&quot;请选择门店&quot;</span>\n        /&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">mi-cell-group</span>&gt;</span>\n\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-button</span> <span class="hljs-attr">round</span> <span class="hljs-attr">block</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;primary&quot;</span> <span class="hljs-attr">native-type</span>=<span class="hljs-string">&quot;submit&quot;</span>&gt;</span>\n        下一步\n    <span class="hljs-tag">&lt;/<span class="hljs-name">mi-button</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">mi-form</span>&gt;</span>\n</code></pre>\n</div><div class="mi-doc-card"><h3 id="gua-yong-chang-jing" tabindex="-1">适用场景</h3>\n<ul>\n<li>报名、预约、审批等步骤明确的移动端表单</li>\n<li>需要先填写基础信息，再确认资料的业务流程</li>\n<li>需要统一字段排列、提交动作和状态提示的录入页</li>\n</ul>\n</div><div class="mi-doc-card"><h3 id="shi-yong-jian-yi" tabindex="-1">使用建议</h3>\n<ul>\n<li>每一步只放当前必须完成的字段，避免移动端页面过长。</li>\n<li>只读字段用于打开选择器、日期选择器或弹层，不直接混入复杂控件。</li>\n<li>提交按钮固定在表单末尾，文案与当前步骤保持一致。</li>\n</ul>\n</div>'},null,8,l))}}}]);